PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE Users ( user_id TEXT PRIMARY KEY, line_display_name TEXT, line_picture_url TEXT, real_name TEXT, phone TEXT, email TEXT, class TEXT DEFAULT '無', level INTEGER DEFAULT 1, current_exp INTEGER DEFAULT 0, tag TEXT, perk TEXT, notes TEXT, username TEXT, role TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP , stored_value_balance INTEGER DEFAULT 0, password TEXT, id TEXT);
CREATE TABLE Purchasehistory ( history_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, exp_added INTEGER NOT NULL, reason TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES Users(user_id) );
CREATE TABLE News ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, category TEXT, published_date TEXT, image_url TEXT, content TEXT, is_published INTEGER DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE StoreInfo ( id INTEGER PRIMARY KEY, address TEXT, phone TEXT, opening_hours TEXT, description TEXT , store_name TEXT);
CREATE TABLE BookingSettings ( disabled_date TEXT PRIMARY KEY );
CREATE TABLE MessageDrafts ( draft_id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, content TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE AppSettings (key TEXT PRIMARY KEY,value TEXT,description TEXT,type TEXT NOT NULL DEFAULT 'string');
CREATE TABLE Products (     product_id TEXT PRIMARY KEY,     name TEXT NOT NULL,     description TEXT,     category TEXT,     images TEXT,     is_visible INTEGER DEFAULT 1,     display_order INTEGER DEFAULT 999,     inventory_management_type TEXT DEFAULT 'none',     stock_quantity INTEGER,     stock_status TEXT,     price_type TEXT DEFAULT 'simple',     price REAL,     price_options TEXT,     spec_1_name TEXT, spec_1_value TEXT,     spec_2_name TEXT, spec_2_value TEXT,     spec_3_name TEXT, spec_3_value TEXT,     spec_4_name TEXT, spec_4_value TEXT,     spec_5_name TEXT, spec_5_value TEXT,     filter_1 TEXT,     filter_2 TEXT,     filter_3 TEXT,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP,     updated_at DATETIME DEFAULT CURRENT_TIMESTAMP , price_weekday REAL, price_friday REAL, price_saturday REAL);
CREATE TABLE Bookings (     booking_id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id TEXT NOT NULL,     contact_name TEXT NOT NULL,     contact_phone TEXT NOT NULL,     booking_date TEXT NOT NULL,     time_slot TEXT NOT NULL,     num_of_people INTEGER NOT NULL,     total_amount REAL,     notes TEXT,     status TEXT NOT NULL DEFAULT 'confirmed',     created_at DATETIME DEFAULT CURRENT_TIMESTAMP , check_out_date TEXT, discount_amount INTEGER DEFAULT 0, final_amount INTEGER, payment_method TEXT, payment_status TEXT DEFAULT 'unpaid');
CREATE TABLE BookingItems (     item_id INTEGER PRIMARY KEY AUTOINCREMENT,     booking_id INTEGER NOT NULL,     item_name TEXT NOT NULL,     quantity INTEGER NOT NULL DEFAULT 1,     price REAL, product_id TEXT NOT NULL DEFAULT '',     FOREIGN KEY (booking_id) REFERENCES Bookings(booking_id) ON DELETE CASCADE );
CREATE TABLE Activities (     activity_id INTEGER PRIMARY KEY AUTOINCREMENT,     type TEXT NOT NULL,     message TEXT NOT NULL,     link TEXT,     is_read INTEGER NOT NULL DEFAULT 0,     created_at DATETIME DEFAULT (datetime('now', 'localtime')) );
CREATE TABLE RoomInventory (   product_id TEXT NOT NULL,   inventory_date TEXT NOT NULL,   status TEXT CHECK(status IN ('Open', 'Closed')) DEFAULT 'Closed',   quantity_available INTEGER DEFAULT 0,   base_price INTEGER,   PRIMARY KEY (product_id, inventory_date),   FOREIGN KEY (product_id) REFERENCES Products(product_id) ON DELETE CASCADE );
CREATE TABLE StoredValueHistory ( history_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, amount_changed INTEGER NOT NULL, current_balance INTEGER NOT NULL, type TEXT NOT NULL CHECK(type IN ('admin_topup', 'admin_deduct', 'booking_payment')), notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES Users(user_id) );
CREATE TABLE VoucherTemplates (     template_id INTEGER PRIMARY KEY AUTOINCREMENT,     internal_name TEXT NOT NULL,     title TEXT NOT NULL,     type TEXT NOT NULL CHECK(type IN ('discount_fixed', 'discount_percentage', 'redeem_item')),     value REAL,     redeem_item_name TEXT,     min_spend REAL DEFAULT 0,     valid_from TEXT,     valid_to TEXT,     applicable_product_ids TEXT,     applicable_days_of_week TEXT,     total_supply INTEGER,     limit_per_user INTEGER DEFAULT 1,     is_public INTEGER DEFAULT 0,     public_claim_code TEXT UNIQUE,     is_active INTEGER DEFAULT 1,     created_at TEXT DEFAULT (datetime('now', 'localtime')) );

CREATE TABLE UserVouchers ( voucher_id INTEGER PRIMARY KEY AUTOINCREMENT, template_id INTEGER NOT NULL, user_id TEXT NOT NULL, is_used INTEGER DEFAULT 0, issued_at DATETIME DEFAULT CURRENT_TIMESTAMP, used_at DATETIME, FOREIGN KEY (template_id) REFERENCES VoucherTemplates(template_id), FOREIGN KEY (user_id) REFERENCES Users(user_id) );

CREATE TABLE RallyCampaigns (   campaign_id INTEGER PRIMARY KEY,   title TEXT NOT NULL,   description TEXT,   required_stamps INTEGER NOT NULL,   reward_voucher_id INTEGER NOT NULL,   start_date TEXT,   end_date TEXT,   is_active INTEGER DEFAULT 1,   created_at TEXT DEFAULT (datetime('now', 'localtime')) , can_repeat INTEGER DEFAULT 0);
CREATE TABLE RallyStations (   station_id INTEGER PRIMARY KEY,   campaign_id INTEGER NOT NULL,   name TEXT NOT NULL,   description TEXT,   unique_partner_code TEXT UNIQUE NOT NULL,   partner_name TEXT,   partner_validation_info TEXT,   expiry_date TEXT,   is_active INTEGER DEFAULT 1,   created_at TEXT DEFAULT (datetime('now', 'localtime')) );
CREATE TABLE UserRallyProgress ( progress_id INTEGER PRIMARY KEY, user_id TEXT NOT NULL, campaign_id INTEGER NOT NULL, station_id INTEGER NOT NULL, stamped_at TEXT DEFAULT CURRENT_TIMESTAMP, is_archived INTEGER DEFAULT 0);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_bookings_user_id ON Bookings(user_id);
CREATE INDEX idx_bookings_date ON Bookings(booking_date);
CREATE INDEX idx_booking_items_booking_id ON BookingItems(booking_id);
CREATE INDEX idx_user_vouchers_user ON UserVouchers(user_id, is_used);
CREATE INDEX idx_user_vouchers_template ON UserVouchers(template_id);
CREATE INDEX idx_voucher_templates_code ON VoucherTemplates (public_claim_code);
CREATE UNIQUE INDEX idx_unique_active_stamp  ON UserRallyProgress (user_id, campaign_id, station_id, is_archived);
