INSERT INTO "News" ("id","title","category","published_date","image_url","content","is_published","created_at") VALUES(35,'萬聖節搞怪佈置完成！','最新消息','2025-10-24','https://placehold.co/600x400/ffab91/333?text=Halloween','民宿大廳已換上萬聖節主題佈置，歡迎拍照留念！',1,'2025-10-26 14:46:08');
INSERT INTO "News" ("id","title","category","published_date","image_url","content","is_published","created_at") VALUES(36,'臉書打卡送小禮物活動','促銷活動','2025-09-10','','入住期間於 Facebook 或 Instagram 打卡標記我們，即可獲得精美小禮物一份。',1,'2025-10-26 14:46:08');
INSERT INTO "News" ("id","title","category","published_date","image_url","content","is_published","created_at") VALUES(37,'官網訂房系統維護公告','最新消息','2025-10-28','','官網訂房系統將於 10/29 凌晨 2:00-4:00 進行維護，屆時可能暫停服務。',1,'2025-10-26 14:46:08');
