INSERT INTO "StoreInfo" ("id","address","phone","opening_hours","description","store_name") VALUES(1,'台中市','0912345678','24小時營業',replace('鐵絲特飯店是一處結合現代設計與舒適氛圍的城市休憩空間，為旅人打造溫暖而安定的落腳之處。\n\n無論是短暫停留或長時間住宿，我們都希望每一位來到這裡的旅客，能在忙碌的旅途中找到片刻的放鬆與自在。\n\n客房空間寬敞舒適，設備齊全，當你推開房門的那一刻剩下的只有安靜、舒適，讓每一晚的休息都成為重新整理心情的時刻。\n','\n',char(10)),'鐵絲特飯店');
