INSERT INTO "MessageDrafts" ("draft_id","title","content","created_at") VALUES(1,'入住須知編輯欄','{"cancellationPolicy":"為維護所有旅客的住宿權益，鐵絲特飯店提供彈性取消政策。\n旅客可於入住日前三日免費取消訂房，將不收取任何費用；\n入住日前三日內取消，將酌收首晚房費作為取消手續費；\n入住當日未到（No Show）則收取全額房費。\n若因不可抗力因素需調整訂單，請提前與飯店聯繫~","checkInInstructions":"入住時間：下午3:00後；退房時間：中午11:00前\n辦理入住請出示有效身分證件\n飯店全館禁菸，違者將酌收清潔費\n訂房完成後須於三日內匯款，未完成匯款視為未成功訂房"}','2025-09-28 21:02:26');
INSERT INTO "MessageDrafts" ("draft_id","title","content","created_at") VALUES(2,'預訂完成自動發送通知',replace('您好，您預訂{{startDate}} ~ {{endDate}}{{roomSummary}}的預約已被預訂完成，金額總共是{{totalAmount}}。\n\n若有任何疑問，歡迎隨時與我們聯繫。','\n',char(10)),'2025-09-28 21:02:26');
INSERT INTO "MessageDrafts" ("draft_id","title","content","created_at") VALUES(6,'預約成功通知','親愛的顧客您好，您已成功預約！提醒您，若要取消預約，請於預約時間 24 小時前告知，謝謝您的合作。','2025-10-09 18:08:44');
INSERT INTO "MessageDrafts" ("draft_id","title","content","created_at") VALUES(7,'預約行前提醒','溫馨提醒：您的預約時間是明天，期待您的光臨！','2025-10-09 18:08:44');
INSERT INTO "MessageDrafts" ("draft_id","title","content","created_at") VALUES(8,'課程開課通知','您好，提醒您報名的課程將於本週六開課，詳細資訊請參考官網公告，期待課堂上見到您！','2025-10-09 18:08:44');
INSERT INTO "MessageDrafts" ("draft_id","title","content","created_at") VALUES(9,'取消預約確認','您好，已收到您的預約取消申請，並為您完成取消，期待您下次再度光臨。','2025-10-09 18:08:44');
