INSERT INTO "Products" ("product_id","name","description","category","images","is_visible","display_order","inventory_management_type","stock_quantity","stock_status","price_type","price","price_options","spec_1_name","spec_1_value","spec_2_name","spec_2_value","spec_3_name","spec_3_value","spec_4_name","spec_4_value","spec_5_name","spec_5_value","filter_1","filter_2","filter_3","created_at","updated_at","price_weekday","price_friday","price_saturday") VALUES('p-001','標準雙人房',replace('以簡約舒適為設計核心，提供寧靜休憩空間。房內設有一張雙人床，搭配柔和燈光與完善設施，如獨立衛浴、冷氣、電視、免費 Wi-Fi 與書桌，滿足旅客商務或休閒需求。窗外可欣賞城市景，讓您在旅途中也能享有片刻放鬆。無論是情侶出遊、好友同住或短期住宿，這裡都是兼具便利與溫馨的理想選擇。\n\n入住須知\n◆ 入住時間為下午 3:00，退房時間為中午 12:00，請依時辦理以維護清潔作業。\n◆ 房內全面禁菸，若需吸菸請至指定吸菸區域。\n◆ 為維護住宿品質，請勿攜帶寵物或進行喧嘩。\n◆ 貴重物品請妥善保管，若有遺失恕不負責。\n◆ 入住時請出示有效證件以便登記。\n◆ 若需加床、延遲退房或其他服務，請提前告知櫃檯，我們將盡力為您安排。','\n',char(10)),'房型','["https://i.pinimg.com/736x/69/90/fc/6990fca269dfbb195d768fd2a2041300.jpg","https://i.pinimg.com/736x/d8/41/38/d84138f6c085b19cc7e1f7046626b5c9.jpg","https://i.pinimg.com/736x/1a/9f/c2/1a9fc2ac8a4961ccc1adf0c3803d65a1.jpg","https://i.pinimg.com/1200x/23/17/55/2317558879c17ce8a3e4beb082bb0bbe.jpg","https://i.pinimg.com/736x/e6/aa/87/e6aa87d0da76dbf343f74868bb6c07d8.jpg"]',1,1,'none',NULL,NULL,'simple',NULL,NULL,'設施說明','加大雙人床：182 公分 x 188 公分','','衛浴設備：提供毛巾、浴巾、吹風機、浴袍','','設施說明：房內提供飲水機、膠囊咖啡機、中央空調','','吹風機、中央空調、洗沐浴乳、膠囊咖啡機',NULL,NULL,NULL,NULL,NULL,'2025-11-02 08:02:55','2025-11-30 06:31:38',2000,2200,2500);
INSERT INTO "Products" ("product_id","name","description","category","images","is_visible","display_order","inventory_management_type","stock_quantity","stock_status","price_type","price","price_options","spec_1_name","spec_1_value","spec_2_name","spec_2_value","spec_3_name","spec_3_value","spec_4_name","spec_4_value","spec_5_name","spec_5_value","filter_1","filter_2","filter_3","created_at","updated_at","price_weekday","price_friday","price_saturday") VALUES('p-002','豪華雙人房',replace('豪華雙人房以現代優雅風格打造，結合舒適與質感，為旅客提供高品質的休憩空間。房內設有柔軟大床、獨立浴缸與乾濕分離衛浴，搭配柔和燈光與細緻擺設，營造出放鬆而私密的氛圍。無論是情侶度假或商務旅程，都能在此享受專屬的舒眠體驗與貼心服務。\n\n入住須知\n◆ 入住時間為下午 3:00，退房時間為中午 12:00，請依時辦理以維護清潔作業。\n◆ 房內全面禁菸，若需吸菸請至指定吸菸區域。\n◆ 為維護住宿品質，請勿攜帶寵物或進行喧嘩。\n◆ 貴重物品請妥善保管，若有遺失恕不負責。\n◆ 入住時請出示有效證件以便登記。\n◆ 若需加床、延遲退房或其他服務，請提前告知櫃檯，我們將盡力為您安排。','\n',char(10)),'房型','["https://i.pinimg.com/1200x/5d/62/58/5d6258500f51be9aae75458c39d1506b.jpg","https://i.pinimg.com/1200x/1c/35/a7/1c35a77d107a9c8cd8cd3c784762b60f.jpg","https://i.pinimg.com/1200x/6e/64/2b/6e642bc26f1d71e6d011e3f92a09ab09.jpg","https://i.pinimg.com/736x/a6/00/eb/a600eb993daafcb85f5c9426838ee4a7.jpg","https://i.pinimg.com/1200x/0c/63/9f/0c639f6d8615f410e0d118b93575a727.jpg"]',1,2,'none',NULL,NULL,'simple',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-11-02 08:02:55','2025-11-02 16:36:11',2800,3000,3300);
INSERT INTO "Products" ("product_id","name","description","category","images","is_visible","display_order","inventory_management_type","stock_quantity","stock_status","price_type","price","price_options","spec_1_name","spec_1_value","spec_2_name","spec_2_value","spec_3_name","spec_3_value","spec_4_name","spec_4_value","spec_5_name","spec_5_value","filter_1","filter_2","filter_3","created_at","updated_at","price_weekday","price_friday","price_saturday") VALUES('p-003','標準四人房',replace('標準四人房擁有寬敞明亮的空間配置，設有兩張雙人床與齊全設施，適合家庭或好友結伴入住。房內採用溫暖色調與簡約設計，營造溫馨舒適的氛圍。搭配獨立衛浴、電視與免費 Wi-Fi，讓每位旅客都能自在放鬆，享受愉快的團體旅行時光。\n\n入住須知\n◆ 入住時間為下午 3:00，退房時間為中午 12:00，請依時辦理以維護清潔作業。\n◆ 房內全面禁菸，若需吸菸請至指定吸菸區域。\n◆ 為維護住宿品質，請勿攜帶寵物或進行喧嘩。\n◆ 貴重物品請妥善保管，若有遺失恕不負責。\n◆ 入住時請出示有效證件以便登記。\n◆ 若需加床、延遲退房或其他服務，請提前告知櫃檯，我們將盡力為您安排。','\n',char(10)),'房型','["https://i.pinimg.com/1200x/94/22/d7/9422d7ecc32a8c6af5d538ef38316de2.jpg","https://i.pinimg.com/1200x/cf/76/7e/cf767ea960a157a05d27e6651f6f175c.jpg","https://i.pinimg.com/1200x/1e/8d/2b/1e8d2bc1536d52753840d6a652c51141.jpg","https://i.pinimg.com/736x/41/65/59/416559704f7add40d26f6544a8c67253.jpg","https://i.pinimg.com/1200x/e0/e7/df/e0e7df9adbd8fc853f341af4758ca212.jpg"]',1,3,'none',NULL,NULL,'simple',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-11-02 08:02:55','2025-11-02 16:36:35',3500,3800,4200);
INSERT INTO "Products" ("product_id","name","description","category","images","is_visible","display_order","inventory_management_type","stock_quantity","stock_status","price_type","price","price_options","spec_1_name","spec_1_value","spec_2_name","spec_2_value","spec_3_name","spec_3_value","spec_4_name","spec_4_value","spec_5_name","spec_5_value","filter_1","filter_2","filter_3","created_at","updated_at","price_weekday","price_friday","price_saturday") VALUES('p-004','豪華四人房',replace('豪華四人房以時尚品味為設計主軸，配置兩張雙人床與獨立起居空間，適合家庭旅遊或多人出行。房內設備完善，包括冰箱、書桌、浴缸與高品質寢具，讓您在寬敞舒適的空間中盡情放鬆。高樓層窗景更為旅程增添一份愜意與尊榮感。\n\n入住須知\n◆ 入住時間為下午 3:00，退房時間為中午 12:00，請依時辦理以維護清潔作業。\n◆ 房內全面禁菸，若需吸菸請至指定吸菸區域。\n◆ 為維護住宿品質，請勿攜帶寵物或進行喧嘩。\n◆ 貴重物品請妥善保管，若有遺失恕不負責。\n◆ 入住時請出示有效證件以便登記。\n◆ 若需加床、延遲退房或其他服務，請提前告知櫃檯，我們將盡力為您安排。','\n',char(10)),'房型','["https://i.pinimg.com/1200x/ba/74/69/ba746972af7d7d7d092c2fff9727c7f3.jpg","https://i.pinimg.com/1200x/80/e7/43/80e74394a37fa0035b79ffc5135b87ac.jpg","https://i.pinimg.com/1200x/12/53/bd/1253bd02ae45c791973a01af07c6ae9f.jpg","https://i.pinimg.com/1200x/a7/2e/db/a72edb5699ca19501887eb476c663845.jpg","https://i.pinimg.com/1200x/ba/25/54/ba25545738701b0245fae8c251ae714e.jpg"]',1,4,'none',NULL,NULL,'simple',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-11-02 08:02:55','2025-11-02 16:36:50',4200,4500,5000);
